fn main() {
    #[cfg(windows)]
    {
        use base64::Engine as _;
        let out = std::path::PathBuf::from(std::env::var("OUT_DIR").expect("OUT_DIR"));
        let icon = out.join("tool-recap.ico");
        let bytes = base64::engine::general_purpose::STANDARD.decode("").expect("decode embedded ico");
        std::fs::write(&icon, bytes).expect("write embedded ico");
        let mut res = winres::WindowsResource::new();
        res.set_icon(icon.to_string_lossy().as_ref());
        res.set("ProductName", "Tool Recap Rust");
        res.set("FileDescription", "AI video recap and voice automation studio");
        res.set("CompanyName", "Tool Recap");
        res.compile().expect("compile Windows resources");
    }
}
